import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { Line, Bar, Pie, Doughnut } from 'react-chartjs-2'; 
import { jsPDF } from "jspdf"; 
import html2canvas from 'html2canvas';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, 
  BarElement, ArcElement, Title, Tooltip, Legend, Filler
} from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, ArcElement, Title, Tooltip, Legend, Filler);

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState("Dashboard");
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("HDFCBANK.NS");
  const [loading, setLoading] = useState(false);
  const [authData, setAuthData] = useState({ username: '', password: '' });

  // 💰 CORE LOGIC STATES
  const [wallet, setWallet] = useState(100000); 
  const [holdings, setHoldings] = useState({}); 
  const [livePrice, setLivePrice] = useState(0); 
  const [priceHistory, setPriceHistory] = useState([]); 
  const prevDecisionRef = useRef(null);

  // ⚙️ SETTINGS & NOTIFICATION STATES (FIXED: All variables defined correctly)
  const [isGhostHedgeActive, setIsGhostHedgeActive] = useState(true);
  const [isAutoExecutionActive, setIsAutoExecutionActive] = useState(true);
  const [isWhatsappEnabled, setIsWhatsappEnabled] = useState(true); 
  const [isAlertEnabled, setIsAlertEnabled] = useState(true); 
  const [sensitivity, setSensitivity] = useState(85);

  // 🚀 NOTIFICATION CONFIG (TELEGRAM SILENT)
  const TELEGRAM_TOKEN = "8260561931:AAFNSYProGiOFw0wPYcam4vS_h-IGh5yL0U";
  const CHAT_ID = "1687190893"; 
  const MY_PHONE = "+919962126306";

  // ✅ Fixed the sendSilentAlert function
  const sendSilentAlert = async (message) => {
    if (!isAlertEnabled) return;

    // 1. 🔵 Telegram Alert (Background)
    const tgUrl = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/sendMessage?chat_id=${CHAT_ID}&text=${encodeURIComponent(message)}`;
    axios.get(tgUrl).catch(e => console.error("Telegram Failed", e));

    // 2. 🟢 WhatsApp Alert (Background via FastAPI)
    try {
        await axios.post('http://localhost:8000/api/send-notification', {
            msg: message,
            phone: MY_PHONE
        });
        console.log("Silent Alerts Dispatched!");
    } catch (error) {
        console.error("WhatsApp Backend Error", error);
    }
  };

  const stockList = [

    { name: "HDFC Bank (₹816 Proof)", symbol: "HDFCBANK.NS" },

    { name: "SBI", symbol: "SBIN.NS" },

    { name: "ICICI Bank", symbol: "ICICIBANK.NS" },

    { name: "Reliance Industries", symbol: "RELIANCE.NS" },

    { name: "TCS", symbol: "TCS.NS" },

    { name: "Infosys", symbol: "INFY.NS" },

    { name: "Adani Enterprises", symbol: "ADANIENT.NS" },

    { name: "ITC", symbol: "ITC.NS" }

  ];
  // 🎲 MONTE CARLO STATES
  const [investment, setInvestment] = useState(10000); // Default ₹10,000
  const [mcResult, setMcResult] = useState(null);

  const runMonteCarlo = () => {
    if (!data) return;
    
    setLoading(true);
    // Simulation Logic: 
    // BSI + Volatility + Ghost Hedge analysis
    setTimeout(() => {
      const bsiVal = parseFloat(data.bsi_score);
      const volVal = parseFloat(data.volatility);
      
      // AI Logic for Verdict
      let projectedProfit = investment * (bsiVal / 100) * (1 - volVal/100);
      let projectedLoss = investment * (volVal / 100);
      let verdict = "";
      let color = "";

      if (bsiVal > 70 && volVal < 30) {
        verdict = "MUST BUY (AI STRONGLY RECOMMENDS)";
        color = "#10b981";
      } else if (bsiVal > 50) {
        verdict = "HOLD (MODERATE RISK)";
        color = "#f59e0b";
      } else {
        verdict = "AVOID (HIGH VOLATILITY DETECTED)";
        color = "#ef4444";
      }

      setMcResult({
        profit: projectedProfit.toFixed(2),
        loss: projectedLoss.toFixed(2),
        verdict: verdict,
        color: color,
        ghostHedgeStatus: volVal > 25 ? "ACTIVE (Shielding Capital)" : "STANDBY"
      });
      setLoading(false);
    }, 1000);
  };
 // 🟢 LIVE SIMULATION: AUTO-SELL ONLY (₹10 GAP)// 🟢 FIXED: PRICE SYNC & SIMULATION
  useEffect(() => {
    if (isLoggedIn && data) {
      // 🚀 Step 1: Stock maathuna udane livePrice-ai backend price-ku force pannanum
      setLivePrice(data.current_price);
      setPriceHistory([data.current_price]);

      const interval = setInterval(() => {
        setLivePrice(prevPrice => {
          // ₹10 target logic-ku yetha maari fluctuation
          const fluctuation = (Math.random() - 0.5) * 6.0; 
          const newPrice = prevPrice + fluctuation;

          // 🛡️ AUTO-SELL LOGIC (₹10 GAP)
          if (isAutoExecutionActive) {
            Object.keys(holdings).forEach(symbol => {
              if (symbol === data.symbol) {
                const holding = holdings[symbol];
                if (holding && holding.qty > 0) {
                  const buyPrice = holding.avgPrice;
                  if (newPrice >= buyPrice + 4.5 || newPrice <= buyPrice - 4.5) {
                    clearInterval(interval); 
                    executeTrade("SELL", true);
                    const reason = newPrice >= buyPrice + 4.5 ? "PROFIT ✅ (+₹10)" : "STOP-LOSS 🛡️ (-₹10)";
                    sendSilentAlert(`🚨 QuantShield AUTO-SELL\nStatus: ${reason}\nStock: ${symbol}\nExit Price: ₹${newPrice.toFixed(2)}`);
                  }
                }
              }
            });
          }

          setPriceHistory(history => [...history, newPrice].slice(-20));
          return newPrice;
        });
      }, 1000);
      return () => clearInterval(interval);
    }
    // ⚠️ IMPORTANT: Inga dependency-la [data] kandippa irukkanum
  }, [data, isLoggedIn, isAutoExecutionActive]);

  // 🤖 AI AUTO TRIGGER (SILENT)
  // 🛑 AI DECISION-A MONITOR PANRA CODE-A DELETE PANNIDUNGA
// Indha maari yedhavadhu code irundha, adhai remove pannunga:
/* useEffect(() => {
  if (data?.decision === "BUY") { executeTrade("BUY", true); }
}, [data]); 
*/

// ✅ IDHU MATTUM DHAAN IRUKANUM (Auto-Sell Only)

// 🔵 2. UPDATED EXECUTION LOGIC (Manual Buy, Auto/Manual Sell)
  const executeTrade = (action, isAuto = false) => {
    if (!data) return;
    const price = livePrice;
    const symbol = data.symbol;

    if (action === "BUY") {
      // Manual Buy: User click panna dhaan nadakkum
      if (wallet >= price) {
        setWallet(prev => prev - price);
        setHoldings(prev => {
          const current = prev[symbol] || { qty: 0, avgPrice: 0 };
          const newQty = current.qty + 1;
          const newAvg = ((current.avgPrice * current.qty) + price) / newQty;
          return { ...prev, [symbol]: { qty: newQty, avgPrice: newAvg } };
        });
        sendSilentAlert(`🛡️ QuantShield 👤 MANUAL BUY\nStock: ${symbol}\nPrice: ₹${price.toFixed(2)}`);
      }
    } else if (action === "SELL") {
      if (holdings[symbol]?.qty > 0) {
        // Correct Calculation: Sale amount based on current live price
        const saleAmount = price * holdings[symbol].qty;
        setWallet(prev => prev + saleAmount);
        
        setHoldings(prev => {
          const updated = { ...prev };
          delete updated[symbol]; // Sell panna udane list-la irundhu remove pannum
          return updated;
        });

        if (!isAuto) {
          sendSilentAlert(`🚨 QuantShield 👤 MANUAL SELL\nStock: ${symbol}\nPrice: ₹${price.toFixed(2)}`);
        }
      }
    }
  };

  const calculatePnL = () => {
    let totalPnL = 0;
    Object.keys(holdings).forEach(symbol => {
      if (data && data.symbol === symbol) totalPnL += (livePrice - holdings[symbol].avgPrice) * holdings[symbol].qty;
    });
    return totalPnL;
  };

  const getAIPriority = (decision, score) => {
  const bsi = parseFloat(score);
  
  if (decision === "BUY" && bsi > 75) return { rank: "STRONG BUY", color: "#10b981", level: 3 };
  if (decision === "BUY") return { rank: "BUY", color: "#34d399", level: 2 };
  if (decision === "HOLD") return { rank: "HOLD", color: "#f59e0b", level: 1 };
  
  // High risk or low score cases
  return { rank: "AVOID", color: "#ef4444", level: 0 };
};
  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        setData(Array.isArray(res.data) ? res.data[0] : res.data);
        setLoading(false);
      }).catch(() => setLoading(false));
  };

  useEffect(() => { if (isLoggedIn) fetchData(selectedStock); }, [selectedStock, isLoggedIn]);

  const downloadReport = () => {
    const input = document.getElementById('report-area');
    html2canvas(input).then((canvas) => {
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      pdf.addImage(imgData, 'PNG', 0, 0, 210, (canvas.height * 210) / canvas.width);
      pdf.save(`QuantShield_Report.pdf`);
    });
  };

  const handleAuth = async () => {
    if(authData.username && authData.password) setIsLoggedIn(true);
    else alert("Please enter credentials");
  };

  const liveGraphData = {
    labels: priceHistory.map((_, i) => `${i}s`),
    datasets: [{ label: `Live Trend (₹)`, data: priceHistory, borderColor: '#00f2fe', backgroundColor: 'rgba(79, 172, 254, 0.1)', fill: true, tension: 0.4, pointRadius: 0 }]
  };

  const pieData = {
    labels: ['Equities', 'Hedge', 'Cash'],
    datasets: [{ data: [60, 25, 15], backgroundColor: ['#00f2fe', '#f87171', '#94a3b8'], borderWidth: 0 }]
  };

  if (!isLoggedIn) {
    return (
      <div style={{ backgroundImage: `linear-gradient(rgba(0, 0, 0, 0.7), rgba(0, 0, 0, 0.7)), url('https://i.ibb.co/XfXkY8C/rm373batch4-07.jpg')`, backgroundSize: 'cover', backgroundPosition: 'center', height: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center', fontFamily: "'Poppins', sans-serif" }}>
        <div style={{ background: 'rgba(255, 255, 255, 0.1)', backdropFilter: 'blur(15px)', padding: '50px', borderRadius: '30px', width: '900px', display: 'flex', gap: '40px', color: 'white', border: '1px solid rgba(255,255,255,0.2)' }}>
          <div style={{ flex: 1 }}>
             <h1 style={{ fontSize: '48px', fontWeight: '900', color: '#00f2fe' }}>QuantShield</h1>
             <p style={{ fontSize: '18px', opacity: 0.8 }}>Advanced AI-Driven Portfolio Optimization and Risk Forecasting System</p>
          </div>
          <div style={{ flex: 0.8, background: 'rgba(0, 0, 0, 0.4)', padding: '40px', borderRadius: '25px' }}>
            <h2 style={{ marginBottom: '20px' }}>LOGIN</h2>
            <input type="text" placeholder="USERNAME" onChange={(e) => setAuthData({...authData, username: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px' }} />
            <input type="password" placeholder="PASSWORD" onChange={(e) => setAuthData({...authData, password: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px' }} />
            <button onClick={handleAuth} style={{ width: '100%', padding: '15px', background: 'linear-gradient(90deg, #00f2fe, #4facfe)', color: '#002f35', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer' }}>SIGN IN</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', backgroundColor: '#f4f7fe', minHeight: '100vh', fontFamily: "'Jakarta Sans', sans-serif" }}>
      
